#!/usr/bin/env python3
"""Fail when an operationId the last release exposed disappears without a breaking note.

Every non-deprecated /api operation of the OSS edition (enterprise-only operations,
tagged `x-mint.metadata.tag: Enterprise`, left out) is served as an MCP tool on
the OSS gateway's /v1/mcp, named after its operationId, so removing, renaming or
deprecating one breaks the agents that call it. This bundles the last release tag's spec and the
working tree's spec from their YAML sources (openapi.json is regenerated by CI
after merge, so the committed bundle may lag), and requires every exposed
operationId the working tree no longer exposes to be named in
transports/changelog.md under a heading that contains "Breaking".

Usage:
    check-openapi-operationids.py [--base-ref <tag>] [--changelog <path>]
"""

import argparse
import json
import re
import subprocess
import sys
import tempfile
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[3]
SPEC_DIR = "docs/openapi"
HTTP_METHODS = {"get", "put", "post", "delete", "patch", "head", "options", "trace", "query"}


def is_enterprise(op):
    return ((op.get("x-mint") or {}).get("metadata") or {}).get("tag") == "Enterprise"


def exposed_operation_ids(spec):
    """operationIds the OSS gateway serves as tools: non-deprecated, OSS, under /api/."""
    ids = set()
    for path, item in (spec.get("paths") or {}).items():
        if not path.startswith("/api/") or not isinstance(item, dict):
            continue
        for method, op in item.items():
            if method in HTTP_METHODS and isinstance(op, dict) and op.get("operationId") and not op.get("deprecated") and not is_enterprise(op):
                ids.add(op["operationId"])
    return ids


def breaking_sections(changelog):
    """The text under every Markdown heading whose title contains "breaking"."""
    sections, current = [], None
    for line in changelog.splitlines():
        heading = re.match(r"^#{1,6}\s+(.*)$", line)
        if heading:
            current = [] if "breaking" in heading.group(1).lower() else None
            if current is not None:
                sections.append(current)
            continue
        if current is not None:
            current.append(line)
    return "\n".join("\n".join(s) for s in sections)


def unannounced_removals(base_ids, head_ids, changelog):
    """Exposed operationIds gone from head and not named under a breaking heading."""
    breaking = breaking_sections(changelog)
    gone = sorted(base_ids - head_ids)
    return [oid for oid in gone if not re.search(r"(?<![A-Za-z0-9_])" + re.escape(oid) + r"(?![A-Za-z0-9_])", breaking)]


def last_release_tag():
    tags = subprocess.run(
        ["git", "tag", "-l", "transports/v*", "--sort=-v:refname"],
        cwd=REPO_ROOT, check=True, capture_output=True, text=True,
    ).stdout.split()
    releases = [t for t in tags if "-" not in t.split("/v", 1)[1]]
    if not releases:
        raise SystemExit("no transports/v* release tag found; fetch tags (actions/checkout with fetch-depth: 0)")
    return releases[0]


def bundle(spec_dir, out):
    subprocess.run([sys.executable, "bundle.py", "--output", str(out)], cwd=spec_dir, check=True, capture_output=True)
    return json.loads(Path(out).read_text())


def bundle_ref(ref, workdir):
    """Bundles docs/openapi as it was at ref, without touching the checkout."""
    archive = subprocess.run(["git", "archive", ref, SPEC_DIR], cwd=REPO_ROOT, check=True, capture_output=True).stdout
    subprocess.run(["tar", "-x", "-C", str(workdir)], input=archive, check=True)
    return bundle(Path(workdir) / SPEC_DIR, Path(workdir) / "base.json")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--base-ref", help="release to compare against (default: the latest transports/v* tag)")
    parser.add_argument("--changelog", default=str(REPO_ROOT / "transports" / "changelog.md"))
    args = parser.parse_args()

    base_ref = args.base_ref or last_release_tag()
    with tempfile.TemporaryDirectory() as tmp:
        base_ids = exposed_operation_ids(bundle_ref(base_ref, tmp))
        head_ids = exposed_operation_ids(bundle(REPO_ROOT / SPEC_DIR, Path(tmp) / "head.json"))
    changelog_path = Path(args.changelog)
    changelog = changelog_path.read_text() if changelog_path.exists() else ""

    missing = unannounced_removals(base_ids, head_ids, changelog)
    print(f"operationIds exposed as MCP tools: {len(base_ids)} at {base_ref}, {len(head_ids)} now")
    if not missing:
        print("ok: every operationId the release exposed is still exposed or announced as breaking")
        return 0
    print(f"\n{len(missing)} operationId(s) exposed at {base_ref} are gone (removed, renamed or deprecated):")
    for oid in missing:
        print(f"  - {oid}")
    print(
        "\noperationIds are the tool names agents call on /v1/mcp. Keep the operationId, or name each one"
        f"\nunder a heading containing \"Breaking\" in {args.changelog}."
    )
    return 1


if __name__ == "__main__":
    sys.exit(main())
